for (const tier of [100,500,2200]) {
 for (const name of ['visible_full','product_default','clustered_90']) {
  const p="'`docs/acceptance/t2208-real-collaboration-baseline/evidence/raw/real-${tier}/api-${name}.json`;
  const j=JSON.parse(fs.readFileSync(p,'"'utf8')).body;
